import type { Project } from './circuit'
import { compileDrawing, sameTerminal, terminalKey, type Drawing, type Terminal } from './drawing'
import { pinsFor } from './devices'
import { layoutElectricallyEquivalent } from './layout-electrical-equivalence'
import type { Measurement } from './probes'
import type { ProbeLayout } from './probe-placement'
import { hasWireCurrentTarget, wireCurrentCut } from './wire-currents'

/** Resolve by actual device-pin membership, never by autogenerated node names or a reused junction ID. */
export function layoutProbeTerminal(before: Drawing, after: Drawing, at: Terminal): Terminal {
  const oldNodes = compileDrawing(before).nodes, newNodes = compileDrawing(after).nodes
  const oldNet = oldNodes.get(terminalKey(at))
  if (oldNet === undefined) throw new Error('原探针端点已不存在，请先重新放置探针。')
  if ('device' in at) {
    const oldDevice = before.devices.find(device => device.id === at.device), newDevice = after.devices.find(device => device.id === at.device)
    if (oldDevice?.kind === newDevice?.kind && newNodes.has(terminalKey(at))) return structuredClone(at)
    throw new Error('探针的器件引脚已改变，请先重新放置探针。')
  }
  const anchors = before.devices.flatMap(device => pinsFor(device).map(pin => ({ device: device.id, pin })))
    .filter(pin => oldNodes.get(terminalKey(pin)) === oldNet).sort((a, b) => terminalKey(a).localeCompare(terminalKey(b)))
  const anchor = anchors.find(pin => newNodes.has(terminalKey(pin)))
  if (!anchor) throw new Error('此电压探针网络没有可确认的器件引脚，请先重新放置探针。')
  const destination = newNodes.get(terminalKey(anchor))
  const destinationPins = after.devices.flatMap(device => pinsFor(device).map(pin => ({ device: device.id, pin })))
    .filter(pin => newNodes.get(terminalKey(pin)) === destination).map(terminalKey).sort()
  if (JSON.stringify(anchors.map(terminalKey).sort()) !== JSON.stringify(destinationPins)) throw new Error('此电压探针的原网络无法唯一对应，请先重新放置探针。')
  return anchor // Stable pins also resolve correctly against each historical Result.
}

function mapLayout(before: Drawing, after: Drawing, at: Terminal, layout?: ProbeLayout): ProbeLayout | undefined {
  if (!layout?.anchor) return layout && structuredClone(layout)
  const oldWire = before.wires.find(wire => wire.id === layout.anchor!.wireId), newWire = after.wires.find(wire => wire.id === layout.anchor!.wireId)
  const mapped = layoutProbeTerminal(before, after, at), nodes = compileDrawing(after).nodes
  if (oldWire && newWire && sameTerminal(oldWire.from, newWire.from) && sameTerminal(oldWire.to, newWire.to) && nodes.get(terminalKey(newWire.from)) === nodes.get(terminalKey(mapped))) return structuredClone(layout)
  // Losing a visual wire anchor must not move the electrical measurement to a different net.
  const { anchor: _anchor, ...rest } = layout
  return Object.keys(rest).length ? structuredClone(rest) : undefined
}

export function remapDrawingMeasurement(before: Drawing, after: Drawing, measurement: Measurement): Measurement {
  if (measurement.kind === 'voltage') return {
    ...measurement, positive: layoutProbeTerminal(before, after, measurement.positive),
    positiveLayout: mapLayout(before, after, measurement.positive, measurement.positiveLayout),
    ...(measurement.negative ? { negative: layoutProbeTerminal(before, after, measurement.negative), negativeLayout: mapLayout(before, after, measurement.negative, measurement.negativeLayout) } : {}),
  }
  if (!measurement.wire) {
    if (before.devices.find(device => device.id === measurement.device)?.kind !== after.devices.find(device => device.id === measurement.device)?.kind) throw new Error('器件电流探针的器件类型已改变。')
    return structuredClone(measurement)
  }
  const target = measurement.wire
  const oldCut = wireCurrentCut(before, target), nextCut = wireCurrentCut(after, target)
  const signature = (cut: ReturnType<typeof wireCurrentCut>) => cut.ok ? JSON.stringify([...new Set(cut.plans.map(plan => JSON.stringify([...plan].sort((a, b) => a.device.localeCompare(b.device)))))].sort()) : null
  if (!hasWireCurrentTarget(after, target) || !oldCut.ok || !nextCut.ok || signature(oldCut) !== signature(nextCut)) {
    throw new Error(`${measurement.id} 导线电流探针的测量支路无法确认，不能沿用旧支路读数。`)
  }
  return structuredClone(measurement)
}

/** Reject the entire layout transaction if even one active branch-current target is ambiguous. */
export function remapLayoutMeasurements(before: Project, after: Project, measurements: Measurement[]): Measurement[] {
  if (!before.drawing || !after.drawing || !layoutElectricallyEquivalent(before, after)) throw new Error('电气结构或参数已有变化，不能作为纯布局保留探针。')
  try { return measurements.map(measurement => remapDrawingMeasurement(before.drawing!, after.drawing!, measurement)) }
  catch (error) { throw new Error(`${(error as Error).message} 原图和探针已保留；请先移除此探针，应用布局后重新放置，或改用器件电流探针。`) }
}

/** Retain the exact old attachment on undo; later user probe edits are migrated instead of overwritten. */
export class LayoutProbeHistory {
  private records: { before: string; after: string; previous: Measurement[]; next: Measurement[] }[] = []
  transition(before: Project, after: Project, measurements: Measurement[]): Measurement[] {
    const beforeKey = JSON.stringify(before), afterKey = JSON.stringify(after), current = JSON.stringify(measurements)
    const record = [...this.records].reverse().find(item => item.before === beforeKey && item.after === afterKey && JSON.stringify(item.previous) === current || item.after === beforeKey && item.before === afterKey && JSON.stringify(item.next) === current)
    if (record) return structuredClone(record.before === beforeKey ? record.next : record.previous)
    const mapped = remapLayoutMeasurements(before, after, measurements)
    this.records.push({ before: beforeKey, after: afterKey, previous: structuredClone(measurements), next: structuredClone(mapped) })
    if (this.records.length > 80) this.records.shift()
    return mapped
  }
}

/** Resolve voltage traces by stable pins in every Result, including fixed historical comparisons. */
export function stableLayoutMeasurements(current: Project, measurements: Measurement[]): Measurement[] {
  if (!current.drawing) return measurements
  return measurements.map(measurement => {
    if (measurement.kind !== 'voltage') return measurement
    try { return { ...measurement, positive: layoutProbeTerminal(current.drawing!, current.drawing!, measurement.positive), ...(measurement.negative ? { negative: layoutProbeTerminal(current.drawing!, current.drawing!, measurement.negative) } : {}) } }
    catch { return measurement } // Keep the record so the existing unavailable-target UI can explain it.
  })
}
